class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # month -> {name: size_bytes}
        self._files_by_month: dict[str, dict[str, int]] = {}
        # name -> owner (last known owner)
        self._owner_by_name: dict[str, str] = {}

    def upload(self, name: str, size_bytes: int, month: str, owner: str = "") -> None:
        if size_bytes == 0:
            raise ValueError("Cannot upload a file of size 0.")

        files = self._files_by_month.setdefault(month, {})

        # Re-uploading an existing name in the same month: no double-count.
        if name in files:
            files[name] = size_bytes
            self._owner_by_name[name] = owner
            return

        if self.used_bytes(month) + size_bytes > self._limit_bytes:
            raise ValueError("Upload would exceed the monthly quota.")

        files[name] = size_bytes
        self._owner_by_name[name] = owner

    def delete(self, name: str, month: str) -> None:
        files = self._files_by_month.get(month)
        if files is not None:
            files.pop(name, None)
        if not any(name in files for files in self._files_by_month.values()):
            self._owner_by_name.pop(name, None)

    def used_bytes(self, month: str) -> int:
        return sum(self._files_by_month.get(month, {}).values())

    def remaining_bytes(self, month: str) -> int:
        return self._limit_bytes - self.used_bytes(month)

    def files(self) -> list[str]:
        names: set[str] = set()
        for files in self._files_by_month.values():
            names.update(files)
        return sorted(names)

    def files_of(self, owner: str) -> list[str]:
        return sorted(
            name for name, file_owner in self._owner_by_name.items()
            if file_owner == owner
        )
